const tenants = [[10, 50], [22, 9000], [13, 40], [4, 60], [7, 30], [15, 45], [11, 35], [8, 55]];
const N = 4;
const load = new Array(N).fill(0);
for (const [id, rps] of tenants) load[id % N] += rps;
const mean = load.reduce((a, b) => a + b, 0) / N;
for (let s = 0; s < N; s++) {
  const hot = load[s] > 2 * mean ? ' HOT' : '';
  console.log(`shard ${s}: ${load[s]} rps${hot}`);
}
console.log(`mean: ${mean} rps`);
